'use strict';

class FunctionsError extends Error {
  constructor(message, name = 'FunctionsError', context) {
    super(message);
    this.name = name;
    this.context = context;
  }
}

class FunctionsHttpError extends FunctionsError {
  constructor(context, ...params) {
    super('Edge Function returned a non-2xx status code', 'FunctionsHttpError', context);
  }
}

class FunctionsRelayError extends FunctionsError {
  constructor(context, ...params) {
    super('Relay Error invoking the Edge Function', 'FunctionsRelayError', context);
  }
}

class FunctionsFetchError extends FunctionsError {
  constructor(context, ...params) {
    super('Failed to send a request to the Edge Function', 'FunctionsFetchError', context);
  }
}

const _getErrorMessage = (err) =>
  err instanceof Error ? err.message : typeof err === 'object' ? JSON.stringify(err) : String(err);

class FunctionsClient {
  constructor(url, { headers = {}, customFetch } = {}) {
    this.url = url;
    this.headers = headers;
    this.fetch = customFetch || fetch;
  }

  setAuth(token) {
    this.headers.Authorization = `Bearer ${token}`;
  }

  async invoke(functionName, options = {}) {
    try {
      const { headers, method, body: functionArgs, signal } = options;
      let _headers = {};
      let body;

      if (functionArgs && (typeof Blob !== 'undefined' && functionArgs instanceof Blob ||
          typeof ArrayBuffer !== 'undefined' && functionArgs instanceof ArrayBuffer ||
          typeof File !== 'undefined' && functionArgs instanceof File ||
          typeof FormData !== 'undefined' && functionArgs instanceof FormData ||
          typeof URLSearchParams !== 'undefined' && functionArgs instanceof URLSearchParams)) {
        body = functionArgs;
      } else if (typeof functionArgs === 'string') {
        body = functionArgs;
      } else if (typeof functionArgs === 'object' && functionArgs !== null) {
        _headers['Content-Type'] = 'application/json';
        body = JSON.stringify(functionArgs);
      }

      const finalHeaders = Object.assign({}, this.headers, _headers, headers);
      const url = `${this.url}/${functionName}`;

      const response = await this.fetch(url, {
        method: method || 'POST',
        headers: finalHeaders,
        body,
        signal,
      });

      const isRelayError = response.headers.get('x-relay-error');
      if (isRelayError) {
        throw new FunctionsRelayError(response);
      }

      if (!response.ok) {
        throw new FunctionsHttpError(response);
      }

      const responseType = (response.headers.get('Content-Type') || 'text/plain').split(';')[0].trim();
      let data;

      if (responseType === 'application/json') {
        data = await response.json();
      } else if (responseType === 'application/octet-stream') {
        data = await response.blob();
      } else if (responseType === 'text/event-stream') {
        data = response;
      } else if (responseType === 'multipart/form-data') {
        data = await response.formData();
      } else {
        data = await response.text();
      }

      return { data, error: null };
    } catch (error) {
      if (error instanceof FunctionsHttpError || error instanceof FunctionsRelayError || error instanceof FunctionsFetchError) {
        return { data: null, error };
      }
      return { data: null, error: new FunctionsFetchError(error) };
    }
  }
}

module.exports = {
  FunctionsClient,
  FunctionsError,
  FunctionsHttpError,
  FunctionsRelayError,
  FunctionsFetchError,
};
